from flask import Flask, request, jsonify
from flask_sqlalchemy import SQLAlchemy

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///database.db'
db = SQLAlchemy(app)

class User(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(80), unique=True, nullable=False)

class GroupMembership(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    group_id = db.Column(db.Integer, db.ForeignKey('group.id'), nullable=False)
    user_id = db.Column(db.Integer, db.ForeignKey('user.id'), nullable=False)

@app.route('/get_group_members', methods=['GET'])
def get_group_members():
    group_id = request.args.get('group_id')

    query = f"SELECT users.username FROM users JOIN group_membership ON users.id = group_membership.user_id WHERE group_membership.group_id = {group_id}"

    members = db.session.execute(query).fetchall()

    return jsonify(members)

if __name__ == '__main__':
    app.run()

import os
from flask import Flask, request, send_from_directory

app = Flask(__name__)
app.config['AVATAR_DIR'] = 'avatars'

@app.route('/upload_avatar', methods=['POST'])
def upload_avatar():
    if 'avatar' not in request.files:
        return "No avatar file."
    avatar_file = request.files['avatar']
    if avatar_file.filename == '':
        return "No file selected."

    username = request.form['username']

    avatar_filename = username + '.png'

    avatar_file.save(os.path.join(app.config['AVATAR_DIR'], avatar_filename))

    return "Avatar uploaded!"

