extracted_headings = []

def get_page_headings(url):
    print(f'Getting headings from {url}')
    r = requests.get(url)
    soup = BeautifulSoup(r.text, 'html.parser')

    for heading in soup.find_all(['h1', 'h2', 'h3']):
        extracted_headings.append(heading.text)

def crawl(url):
    if url in visited:
        return

    visited.add(url)
    get_page_headings(url)

    links = extract_links(url)

    for link in links:
        if 'example.com' in link and '.css' not in link:
            crawl(link)

def extract_links(url):
    r = requests.get(url)
    soup = BeautifulSoup(r.text, 'html.parser')
    links = []

    for a in soup.find_all('a'):
        link = a.get('href')
        if link:
            links.append(link)

    return links

